insert into public.guides (slug, title, category, agency, jurisdiction, audience, summary, eligibility_caveats, helpful_notes, fees_text, processing_time_text, related_slugs, status, content_version, last_verified_on, published_at) values ('sss-membership', 'Getting started with SSS', 'government', 'Social Security System (SSS)', 'PH', 'First-time employees, freelancers and self-employed people who need an SSS number.', 'The SSS runs social insurance for private-sector workers. Most people need an SS number when they start working, and employers commonly ask for it during onboarding.', 'Requirements differ by situation and change over time. Treat this as a planning checklist and confirm every requirement on the official website or with the agency before you go.', 'Only use the official SSS website and channels. SSS does not ask for your password through text messages.', null, null, array['first-job-requirements','philhealth-membership','pagibig-membership']::text[], 'in_review', 0, null, null) on conflict (slug) do nothing;
insert into public.guide_requirements (guide_id, position, text) values ((select id from public.guides where slug = 'sss-membership'), 1, 'A valid ID or supporting document (check the SSS list of accepted documents)') on conflict do nothing;
insert into public.guide_requirements (guide_id, position, text) values ((select id from public.guides where slug = 'sss-membership'), 2, 'Your basic personal details') on conflict do nothing;
insert into public.guide_requirements (guide_id, position, text) values ((select id from public.guides where slug = 'sss-membership'), 3, 'A working e-mail address if you register online') on conflict do nothing;
insert into public.guide_steps (guide_id, position, title, body, is_optional, suggested_offset_days) values ((select id from public.guides where slug = 'sss-membership'), 1, 'Check if you already have an SS number', 'If you had a previous job, you may already have one. Avoid registering twice — ask your previous employer or SSS if unsure.', false, 0) on conflict do nothing;
insert into public.guide_steps (guide_id, position, title, body, is_optional, suggested_offset_days) values ((select id from public.guides where slug = 'sss-membership'), 2, 'Open the official SSS website', 'Use the official site linked below to find the current registration process for your membership type (employee, self-employed, voluntary, OFW).', false, 1) on conflict do nothing;
insert into public.guide_steps (guide_id, position, title, body, is_optional, suggested_offset_days) values ((select id from public.guides where slug = 'sss-membership'), 3, 'Prepare the documents SSS asks for', 'Gather the documents listed on the official page for your situation.', false, 3) on conflict do nothing;
insert into public.guide_steps (guide_id, position, title, body, is_optional, suggested_offset_days) values ((select id from public.guides where slug = 'sss-membership'), 4, 'Register and keep your SS number safe', 'Note only the last 4 digits in AdultingOS. Keep the full number in a secure place.', false, 7) on conflict do nothing;
insert into public.guide_steps (guide_id, position, title, body, is_optional, suggested_offset_days) values ((select id from public.guides where slug = 'sss-membership'), 5, 'Give your SS number to your employer', 'If you are employed, your employer handles contributions once they have your number.', true, 10) on conflict do nothing;
